/* Generated by tools/build.js from data/cloud-plus.js. Edit that file, not this one. */
CertHub.register({"id":"cloud-plus","vendor":"CompTIA","name":"CompTIA Cloud+","short":"Cloud+","exam":"CV0-004","blurb":"Vendor-neutral cloud certification for cloud and systems administrators: architecture, deployment, operations, security, DevOps fundamentals and troubleshooting across public, private and hybrid clouds.","status":"check","statusNote":"Domains and weights (Cloud Architecture 23%, Deployment 19%, Operations 17%, Security 19%, DevOps Fundamentals 10%, Troubleshooting 12%) come from CompTIA's published CV0-004 exam objectives as best known. comptia.org could not be opened from this environment on Sept 25, 2026, so confirm the domains, weights, exam length and passing score on the official CompTIA Cloud+ page and objectives PDF before booking.","lastVerified":"2026-09-25","notices":[],"examInfo":{"questions":"Up to 90 (multiple choice and performance-based)","minutes":90,"pass":"750 on a 100–900 scale","extra":"CompTIA recommends 2–3 years of systems administration or networking experience, with Network+ and Server+ level knowledge. Confirm current details on the official page."},"examSim":{"questions":90,"minutes":90},"sources":[{"label":"CompTIA Cloud+ (CV0-004) certification page and exam objectives","url":"https://www.comptia.org/certifications/cloud"}],"planWeeks":12,"hoursPerWeek":"6–8","domains":[{"id":1,"name":"Cloud architecture","w":23,"topics":["Cloud service models (IaaS, PaaS, SaaS, FaaS) and the shared responsibility model","Deployment models: public, private, hybrid, community and multicloud","Regions, availability zones, edge locations and designing for high availability","Virtualization and compute: hypervisors, instance families, dedicated hosts and multitenancy","Containers, orchestration and serverless compared with virtual machines","Microservices, event-driven architecture, message queues and API gateways","Cloud storage types: block, file and object; storage tiers and performance (IOPS, throughput)","Virtual networks: VPC/VNet design, CIDR planning, subnets, route tables, NAT and internet gateways","Hybrid connectivity: site-to-site VPN, dedicated interconnects, peering and transit hubs","Load balancing, DNS routing and content delivery networks","Disaster recovery architectures: backup and restore, pilot light, warm standby, multisite active-active; RPO and RTO","Cloud cost models: on-demand, reserved and committed use, spot, tagging for showback and chargeback"],"notes":["Domain 1.0 Cloud Architecture objectives (23%)"],"labs":["AWS, Azure or Google Cloud free tier: create a virtual network with one public and one private subnet across two availability zones, add a route table for each and draw the result. Networks and subnets are free, but do not create a NAT gateway (it bills by the hour); delete everything when finished.","Free tier: create an object storage bucket, upload a file, set a lifecycle rule that moves objects to an archive tier after 30 days, and confirm the bucket blocks public access. Stay under the free storage allowance and delete the bucket at the end.","Use the free AWS Pricing Calculator, Azure Pricing Calculator or Google Cloud Pricing Calculator (no account charges) to price one small web app three ways: on-demand, 1-year reserved/committed use and spot. Write down when each model makes sense."]},{"id":2,"name":"Deployment","w":19,"topics":["Deployment strategies: blue-green, canary, rolling, in-place and A/B releases, with rollback plans","Migration strategies: rehost, replatform, refactor, repurchase, retire and retain","Migration planning: discovery, dependency mapping, pilot waves, cutover and validation","Online vs offline data transfer, transfer appliances and database migration with minimal downtime","Provisioning compute: choosing instance size and type, images and templates, golden images","Provisioning storage: volume types, thin vs thick provisioning, replication and encryption settings","Deploying managed services: managed databases, read replicas, caches and managed Kubernetes","Infrastructure as code for deployment: templates, parameters, state and repeatable environments","Immutable infrastructure and environment separation: development, test, staging and production","Post-deployment validation: smoke tests, health checks, performance baselines and documentation"],"notes":["Domain 2.0 Deployment objectives (19%)"],"labs":["Free tier: launch one free-tier eligible Linux VM from a marketplace image, install a web server with a startup (user data / cloud-init) script, browse to it, then terminate it and confirm its disk was deleted too.","Locally with free tools: install Terraform (or OpenTofu) and Docker, and use the Docker provider to deploy an nginx container from code. Run plan, apply, change the port, apply again and destroy, and note how state tracks each change. No cloud account or cost involved.","Locally with Docker Compose: run two versions of a simple web app behind an nginx reverse proxy and switch the proxy between them to practice a blue-green cutover and rollback. No cloud resources, so nothing to bill."]},{"id":3,"name":"Operations","w":17,"topics":["Observability: metrics, logs and traces; dashboards, baselines and alert thresholds","Log aggregation, retention and synthetic monitoring for user-facing services","Scaling: horizontal vs vertical, autoscaling policies (target tracking, scheduled, step) and cooldowns","Backup types (full, incremental, differential, snapshots), retention and the 3-2-1 rule","Restore testing, immutable and cross-account backups, and protecting backups from ransomware","Patch and update management for VMs, images, containers and managed services","Resource lifecycle: provider deprecations, version upgrades, end of support and decommissioning","Right-sizing, capacity planning and storage lifecycle policies to control cost","Service level agreements, SLOs and availability math (99.9% vs 99.99%)","Operational automation: scheduled start and stop, runbooks and self-healing"],"notes":["Domain 3.0 Operations objectives (17%)"],"labs":["Free tier: on a free-tier VM, create a CPU utilization alarm (CloudWatch, Azure Monitor or Cloud Monitoring) that emails you above 70%, then run a stress tool for five minutes to trigger it. Delete the VM and alarm afterward; alarms beyond the free allowance can bill.","Free tier: take a snapshot of a small VM disk, create a new disk from it, attach it and confirm the files are there, then delete both the snapshot and the extra disk, since snapshots keep billing after the VM is gone.","Locally: run Prometheus and Grafana with Docker Compose, scrape node_exporter from your own machine, build a CPU and memory dashboard and add an alert rule. Everything runs free on your computer."]},{"id":4,"name":"Security","w":19,"topics":["Identity and access management: users, groups, roles, policies and least privilege","Federation and single sign-on (SAML, OpenID Connect), MFA and protecting the root or global admin account","Workload identities: instance roles, managed identities and service accounts instead of stored keys","Secrets and key management: KMS, HSMs, customer-managed keys, rotation and secrets managers","Data protection: encryption at rest and in transit, tokenization, data classification and DLP","Network security controls: security groups vs network ACLs, WAF, DDoS protection and private endpoints","Zero trust and segmentation for cloud workloads","Vulnerability management: scanning hosts, container images and IaC; CSPM for misconfigurations","Compliance and governance: data sovereignty, regulatory frameworks, policy enforcement and audit logs","Hardening: CIS benchmarks, secure baselines, disabling unused services and endpoint protection","Cloud incident response: containment, evidence preservation with snapshots and logs, and recovery"],"notes":["Domain 4.0 Security objectives (19%)"],"labs":["Free tier: turn on MFA for the account's root or global admin user, create a separate admin user for daily work and a read-only user, then sign in as the read-only user and confirm it cannot create resources. IAM is free.","Free tier: create a VM that reads from an object storage bucket using an instance role, managed identity or service account instead of access keys, and confirm no credentials are stored on the disk. Delete the VM and bucket afterward.","Locally with free tools: scan a public container image with Trivy and a Terraform folder with Checkov or tfsec, then fix one high finding in each and scan again. No cloud account needed."]},{"id":5,"name":"DevOps fundamentals","w":10,"topics":["Source control with Git: branches, pull requests, merges and tagging releases","Continuous integration: automated builds, unit tests and artifact creation","Continuous delivery vs continuous deployment, approval gates and pipeline stages","Infrastructure as code tools: declarative vs imperative, Terraform, CloudFormation, ARM/Bicep","Configuration management: Ansible, Puppet and Chef; agent vs agentless; idempotency","APIs, webhooks and data formats (JSON, YAML) for cloud automation","Container images, registries, tagging and promoting one build through environments","Scripting for cloud administration: CLI tools, Bash, PowerShell and Python"],"notes":["Domain 5.0 DevOps Fundamentals objectives (10%)"],"labs":["Free GitHub account: create a repository, work on a feature branch, open a pull request, merge it and tag the release. Add a GitHub Actions workflow that lints a script on every push (free for public repositories).","Locally: write an Ansible playbook that installs and starts nginx on a local VM or container, run it twice and confirm the second run reports no changes (idempotency). Free, nothing billed.","Locally: write a Dockerfile for a small web app, build and tag it, push it to a free registry account (Docker Hub or GitHub Container Registry), then pull and run that exact tag on another machine or VM."]},{"id":6,"name":"Troubleshooting","w":12,"topics":["The troubleshooting methodology applied to cloud incidents","Network troubleshooting: routes, security groups, NACLs, DNS, NAT and peering problems","Access and permission failures: policy evaluation, explicit deny, expired credentials and certificates","Deployment failures: quotas and service limits, template errors, capacity and image problems","Performance problems: resource contention, throttling and API rate limits, latency and bottlenecks","Cost and billing anomalies: orphaned resources, data egress charges and runaway autoscaling","Using logs, metrics, traces and provider health dashboards to find root cause","Automation and integration failures: broken pipelines, expired tokens, version and dependency mismatches"],"notes":["Domain 6.0 Troubleshooting objectives (12%)"],"labs":["Free tier: launch a VM, deliberately remove the inbound SSH/RDP rule from its security group, confirm the connection times out, read the flow logs or connection test tool, then restore the rule. Terminate the VM when done.","Free tier: create a user with a policy that allows reading a bucket, then add an explicit deny and use the provider's policy simulator or access analyzer to explain why access fails. Delete the test user and bucket afterward.","Free tier: turn on a billing budget with an alert at a few dollars, then use the cost explorer or cost analysis page to look for leftover disks, snapshots and public IPs from earlier labs and delete them."]}],"study":{"1":[["Compare IaaS, PaaS, SaaS and FaaS by what the customer manages.","IaaS: the customer manages the OS, runtime, apps and data on provider infrastructure. PaaS: only the app and data. SaaS: just users, settings and data. FaaS: only function code and its configuration; the provider runs and scales it per event."],["Explain the shared responsibility model for an IaaS VM.","The provider secures the physical facilities, hardware, network and hypervisor. The customer secures the guest OS (patching, hardening), applications, identities, network rules such as security groups, and data, including encryption choices."],["What is the difference between a region and an availability zone, and why does it matter?","A region is a geographic area; availability zones are separate data centers within it with independent power and networking, linked by low-latency links. Spreading across zones survives a data center failure; spreading across regions survives a regional outage and helps with data residency."],["When would you use block, file and object storage?","Block for low-latency disks attached to one VM, such as databases. File for shared file systems many servers mount over NFS or SMB. Object for massive, HTTP-accessed data such as backups, media and logs, with lifecycle tiers."],["Order the DR architectures from cheapest to fastest recovery.","Backup and restore (cheapest, slowest RTO), pilot light (core data replicated, other servers off), warm standby (scaled-down copy running), multisite active-active (full capacity in two places, near-zero RTO and highest cost)."],["When do reserved instances beat spot instances, and vice versa?","Reserved or committed use suits steady 24x7 workloads you will run for one to three years. Spot suits interruptible, fault-tolerant work such as batch jobs, CI runners and rendering, because the provider can reclaim capacity at short notice."]],"2":[["Contrast blue-green, canary and rolling deployments.","Blue-green builds a full second environment and switches all traffic at once, with fast rollback by switching back. Canary sends a small share of users to the new version first and widens it if metrics stay healthy. Rolling replaces instances in batches, keeping partial capacity without a second full environment."],["Name the common migration strategies and one example of each.","Rehost: lift-and-shift VMs unchanged. Replatform: move a database to a managed service with small changes. Refactor: rebuild as microservices or serverless. Repurchase: replace an app with SaaS. Retire: shut down unused apps. Retain: keep on premises for now."],["When is an offline transfer appliance better than sending data over the network?","When the data set is large enough that the available bandwidth would take weeks or months, for example hundreds of terabytes over a 100 Mbps link. The appliance is filled on site and shipped to the provider."],["What is a golden image and why use one?","A pre-built, hardened and patched VM or container image with required agents and settings. It makes deployments faster and consistent and reduces configuration drift; it must be rebuilt regularly to stay patched."],["What should you check right after a deployment?","Health checks and smoke tests of key functions, logs for errors, performance compared with the baseline, monitoring and alerting coverage, security settings, and updated documentation, with the rollback plan ready if checks fail."]],"3":[["What do metrics, logs and traces each tell you?","Metrics are numeric time series (CPU, latency, error rate) good for dashboards and alerts. Logs are detailed event records for investigation. Traces follow one request across services to show where time is spent."],["Compare horizontal and vertical scaling.","Horizontal scaling adds or removes instances behind a load balancer and suits stateless apps with no downtime. Vertical scaling changes an instance's size, usually needs a restart and hits a ceiling at the largest size."],["Which backups do you need to restore after full, incremental and differential schemes?","Full: just the last full. Incremental: the last full plus every incremental since. Differential: the last full plus only the latest differential. Incrementals are fastest to take, differentials faster to restore."],["How do you protect backups from ransomware in the cloud?","Keep copies in a separate account or subscription with separate credentials, use immutable storage or object lock, apply retention policies, encrypt them, restrict delete permissions and test restores regularly."],["How much downtime do 99.9% and 99.99% allow per 30-day month?","About 43 minutes for 99.9% and about 4.3 minutes for 99.99%. A chain of dependent services has lower availability than any single one, because their availabilities multiply."]],"4":[["Why use instance roles, managed identities or service accounts instead of access keys?","The platform issues short-lived credentials automatically, so there are no long-lived keys to leak in code, images or repositories, and permissions can be scoped and audited per workload."],["Contrast security groups and network ACLs.","Security groups apply to instances or interfaces, are stateful (return traffic is allowed automatically) and usually support allow rules only. Network ACLs apply to subnets, are stateless (return traffic needs its own rule) and support ordered allow and deny rules."],["What does a customer-managed key give you over a provider-managed key?","Control over the key's policy, rotation, disabling and deletion, plus audit logs of its use. Disabling the key makes the encrypted data unreadable, which supports compliance and crypto-shredding."],["How does data sovereignty affect cloud design?","Laws may require certain data to stay in a specific country or region. Choose compliant regions, block others with policy, check where backups, replicas and logs are stored, and review provider contracts."],["What are the first steps when a cloud VM is suspected of compromise?","Contain it (move it to an isolation security group, revoke its role credentials), preserve evidence (disk snapshots, memory if possible, logs), investigate using audit logs, then eradicate and rebuild from a known-good image."]],"5":[["What is the difference between continuous delivery and continuous deployment?","Both automatically build, test and prepare every change. Continuous delivery keeps a manual approval before production; continuous deployment releases every change that passes the pipeline to production automatically."],["Compare declarative and imperative infrastructure as code.","Declarative code describes the desired end state and the tool works out the steps (Terraform, CloudFormation, Bicep). Imperative code lists the steps to run in order (scripts, CLI commands)."],["What does idempotent mean in configuration management?","Running the same configuration many times gives the same result; a second run changes nothing if the system is already in the desired state. Ansible modules are designed this way."],["Why build a container image once and promote it through environments?","The exact artifact tested in development and staging is the one that runs in production, avoiding differences from rebuilding. Use immutable tags or digests rather than 'latest'."],["What is a webhook?","An HTTP callback: when an event happens (such as a push to a repository), one system sends an HTTP POST to a URL registered by another system, which then acts, for example by starting a pipeline."]],"6":[["List the CompTIA troubleshooting steps in order.","Identify the problem; establish a theory of probable cause; test the theory; establish a plan of action and identify effects; implement the solution or escalate; verify full system functionality and implement preventive measures; document findings, actions and outcomes."],["A VM in a private subnet cannot download updates. What do you check?","The subnet's route table for a default route to a NAT gateway or instance, that the NAT sits in a public subnet with a route to the internet gateway, outbound security group and NACL rules (including return ports for stateless NACLs), and DNS resolution."],["An API call returns HTTP 429. What does it mean and how do you fix it?","Too many requests: the service is throttling the caller. Add exponential backoff with jitter and retries, spread or batch requests, cache results, or request a higher rate limit."],["A deployment fails with a quota or limit error. What are your options?","Check the service quota in that region, request an increase, deploy to another region or zone, choose a different instance type, or clean up unused resources that count against the limit."],["The monthly bill jumped unexpectedly. Where do you look?","Cost explorer by service, region and tag; data transfer (egress and cross-region) charges; orphaned disks, snapshots, IPs and load balancers; autoscaling that did not scale in; and new resources without owner tags."]]},"qCount":90,"hasLessons":true,"hasPbqs":true});
